function gsRules(string $documentType):array{$all=array_values(array_filter(gsWalk(GF_SMART_KNOWLEDGE),fn($f)=>gsSupported($f)));$needle=mb_strtolower($documentType,'UTF-8');$score=function(array$f)use($needle):int{$n=mb_strtolower(((string)($f['path']??'')).' '.((string)($f['name']??'')),'UTF-8');$s=0;foreach(['engel','qs','gf','taskforce','master','arbeitsstandard','richtlinie','regress']as$w)if(str_contains($n,$w))$s+=12;if($needle!==''&&str_contains($n,$needle))$s+=30;return$s;};usort($all,fn($a,$b)=>$score($b)<=>$score($a));return array_slice($all,0,6);}
